function sliderStages() {
  if (typeof Swiper === 'undefined' || typeof gsap === 'undefined' || typeof ScrollTrigger === 'undefined') {
    console.error('Требуется Swiper, gsap и ScrollTrigger');
    return;
  }

  var thumbSwiper = new Swiper(".stages__wrap .mySwiper", {
    slidesPerView: 4,
    spaceBetween: 16,
    freeMode: true,
  });

  var isMobile = window.innerWidth < 993;

  var mainSwiper = new Swiper(".stages__wrap .mySwiper2", {
    slidesPerView: 1,
    spaceBetween: 0,
    speed: 1200,
    direction: "vertical",
    mousewheel: false,              
    allowTouchMove: isMobile,       
    autoHeight: true,
    thumbs: { swiper: thumbSwiper },
    pagination: { el: ".stages__pagination", type: "progressbar" },
    breakpoints: {
      320: {
        slidesPerView: 1,
        spaceBetween: 50,
        mousewheel: false,
        allowTouchMove: true,
      },
      993: {
        slidesPerView: 1,
        spaceBetween: 0,
      },
    },
    if (isMobile) {
    try {
        mainSwiper.params.touchReleaseOnEdges = true;
        mainSwiper.touchReleaseOnEdges = true;
        mainSwiper.update(); 
    } catch (e) {
        console.warn('Не удалось включить touchReleaseOnEdges', e);
    }
    }
  });

  function updateActiveYear() {
    const activeIndex = mainSwiper.activeIndex;
    const activeThumb = thumbSwiper.slides[activeIndex];
    const activeMonth = activeThumb ? activeThumb.getAttribute('data-month') : null;

    document.querySelectorAll('.year').forEach(y => y.classList.remove('year--active'));
    if (activeMonth) {
      const el = document.querySelector(`.year[data-year="${activeMonth}"]`);
      if (el) el.classList.add('year--active');
    }
  }
  updateActiveYear();
  mainSwiper.on('slideChange', updateActiveYear);

  document.querySelectorAll('.year').forEach(year => {
    year.addEventListener('click', function() {
      const selectedYear = this.getAttribute('data-year');
      let targetIndex = -1;
      thumbSwiper.slides.forEach((slide, index) => {
        if (slide.getAttribute('data-month') === selectedYear && targetIndex === -1) {
          targetIndex = index;
        }
      });
      if (targetIndex !== -1) {
        mainSwiper.slideTo(targetIndex);
        syncScrollToIndex(targetIndex, true);
      }
    });
  });

  if (isMobile) return;

  var slidesCount = mainSwiper.slides ? mainSwiper.slides.length : 0;
  if (!slidesCount || slidesCount <= 1) return;

  var proxy = { idx: 0 };
  var lastIdx = -1;

  var tl = gsap.timeline({
    scrollTrigger: {
      trigger: ".stages__wrap",
      start: "top top",
      end: () => "+=" + (window.innerHeight * (slidesCount - 1)),
      pin: true,
      anticipatePin: 1,
      scrub: 0.5,
      snap: {
        snapTo: 1 / (slidesCount - 1),
        duration: 0.16,
        ease: "power1.out",
        inertia: false
      },
      invalidateOnRefresh: true,
      onEnter: () => { mainSwiper.allowTouchMove = false; },
      onEnterBack: () => { mainSwiper.allowTouchMove = false; },
      onLeave: () => { mainSwiper.allowTouchMove = true; },
      onLeaveBack: () => { mainSwiper.allowTouchMove = true; }
    }
  });

  tl.to(proxy, {
    idx: slidesCount - 1,
    ease: "none",
    onUpdate: function() {
      var idx = Math.round(proxy.idx);
      if (idx !== lastIdx) {
        lastIdx = idx;
        mainSwiper.slideTo(idx);
      }
    }
  });

  ScrollTrigger.refresh();

  function syncScrollToIndex(index, instant) {
    if (!tl || !tl.scrollTrigger || slidesCount <= 1) return;

    var st = tl.scrollTrigger;

    if (typeof st.start !== 'number' || typeof st.end !== 'number') {
      ScrollTrigger.refresh(); 
      st = tl.scrollTrigger;
    }

    if (typeof st.start !== 'number' || typeof st.end !== 'number') return;

    var fraction = (slidesCount - 1) === 0 ? 0 : (index / (slidesCount - 1));
    var targetScroll = Math.round(st.start + fraction * (st.end - st.start));

    var cur = window.pageYOffset || document.documentElement.scrollTop || document.body.scrollTop || 0;
    if (Math.abs(cur - targetScroll) <= 2) {
      proxy.idx = index;
      lastIdx = index;
      try { tl.progress(fraction, false); } catch (e) {}
      return;
    }

    proxy.idx = index;
    lastIdx = index;

    try { tl.progress(fraction, false); } catch (e) {}

    if (instant) {
      window.scrollTo(0, targetScroll);
    } else {
      window.scrollTo({ top: targetScroll, left: 0, behavior: 'smooth' });
    }
  }

  mainSwiper.on('slideChange', function() {
    var idx = mainSwiper.activeIndex;
    syncScrollToIndex(idx, true);
  });

  (function attachThumbClicks() {
    var wrap = document.querySelector('.stages__wrap .mySwiper');
    if (!wrap) return;
    wrap.addEventListener('click', function(e) {
      var slideEl = e.target.closest('.swiper-slide');
      if (!slideEl) return;
      var slides = Array.prototype.slice.call(wrap.querySelectorAll('.swiper-slide'));
      var index = slides.indexOf(slideEl);
      if (index === -1) return;
      mainSwiper.slideTo(index, 0);
      syncScrollToIndex(index, true);
    });
  })();

  (function() {
    var lock = false;
    var wrap = document.querySelector('.stages__wrap');
    if (!wrap) return;

    function onWheel(e) {
      var st = ScrollTrigger.getAll().find(t => t.trigger === wrap);
      if (!st || !st.isActive) return;  

      if (lock) {
        e.preventDefault();
        return;
      }

      if (Math.abs(e.deltaY) < 5) return;

      lock = true;

      if (e.deltaY > 0) {
        // вниз
        if (mainSwiper.activeIndex < slidesCount - 1) {
          mainSwiper.slideNext();
        } else {
          var endPos = st.end;
          if (typeof endPos === 'number') {
            window.scrollTo({ top: endPos + 1, left: 0, behavior: 'auto' });
          } else {
            window.scrollBy({ top: window.innerHeight * 0.5, left: 0, behavior: 'auto' });
          }
        }
      } else {
        if (mainSwiper.activeIndex > 0) {
          mainSwiper.slidePrev();
        } else {
          var startPos = st.start;
          if (typeof startPos === 'number') {
            window.scrollTo({ top: startPos - 1, left: 0, behavior: 'auto' });
          } else {
            window.scrollBy({ top: -window.innerHeight * 0.5, left: 0, behavior: 'auto' });
          }
        }
      }

      setTimeout(function() { lock = false; }, 300);
      e.preventDefault();
    }

    wrap.addEventListener('wheel', onWheel, { passive: false });
  })();

  var resizeTimer;
  function refreshScrollTrigger() {
    slidesCount = mainSwiper.slides.length || slidesCount;
    ScrollTrigger.refresh();
  }
  window.addEventListener('resize', function() {
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(refreshScrollTrigger, 120);
  });
}

